#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    // The original program expects at least two arguments: shift and text.
    // If the usage is incorrect, it prints "USAGE" and exits.
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    // Parse the shift value (allow optional leading '+' or '-')
    char *endptr;
    long shift_val = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') { // non‑numeric characters
        puts("USAGE");
        return 0;
    }

    // Normalise shift to the range 0‑25 (the original binary does this with a magic‑constant division).
    int shift = (int)shift_val;
    shift = ((shift % 26) + 26) % 26; // ensure non‑negative remainder

    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > 0x400) { // original limit is 1024 bytes
        puts("USAGE");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (c >= 'A' && c <= 'Z') {
            c = (c - 'A' + shift) % 26 + 'A';
        } else if (c >= 'a' && c <= 'z') {
            c = (c - 'a' + shift) % 26 + 'a';
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
